rules.logic:
element.style.position = 'sticky';
element.style.top = '8px';
element.style.maxHeight = 'calc(100vh - 16px)';
element.style.overflowY = 'auto';
element.style.overflowX = 'hidden';
element.style.zIndex = '100';
element.style.boxShadow = '0 2px 12px rgba(0,0,0,0.18)';
element.style.borderRadius = '6px';
element.style.background = 'var(--background-color-base, #fff)';
element.style.scrollbarWidth = 'thin';

element.style.fontSize = '0.78em';
element.style.lineHeight = '1.25';
element.style.letterSpacing = '-0.01em';
element.style.margin = '0.1em 0';
element.style.padding = '2px 6px';
element.style.background = 'var(--background-color-neutral-subtle, #f8f9fa)';
element.style.borderRadius = '4px';
element.style.borderLeft = '3px solid var(--border-color-progressive, #3366cc)';

const uls = element.querySelectorAll('ul');
uls.forEach(ul => {
  ul.style.margin = '0';
  ul.style.padding = '0';
  ul.style.listStyle = 'none';
  ul.style.display = 'flex';
  ul.style.flexWrap = 'wrap';
  ul.style.gap = '0';
});

const lis = element.querySelectorAll('li');
lis.forEach(li => {
  li.style.margin = '0';
  li.style.padding = '0 2px';
  li.style.display = 'inline';
  li.style.lineHeight = '1.3';
});
